SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(100) NOT NULL UNIQUE,
    email VARCHAR(190) NULL,
    phone VARCHAR(50) NULL,
    password_hash VARCHAR(255) NOT NULL,
    is_admin TINYINT(1) NOT NULL DEFAULT 0,
    department VARCHAR(50) NOT NULL DEFAULT 'general_admin',
    starting_cash DECIMAL(32,16) NOT NULL DEFAULT 0,
    profile_picture LONGTEXT NULL,
    profile_picture_name VARCHAR(255) NULL,
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    last_login DATETIME NULL,
    last_active_at DATETIME NULL,
    active_session_id VARCHAR(128) NULL,
    last_device_token VARCHAR(128) NULL,
    recovery_code_hash VARCHAR(255) NULL,
    recovery_code_plain VARCHAR(255) NULL,
    recovery_code_plain_masked VARCHAR(30) NULL,
    recovery_code_created_at DATETIME NULL,
    recovery_code_last_used_at DATETIME NULL,
    two_factor_secret TEXT NULL,
    two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0,
    two_factor_updated_at DATETIME NULL,
    two_factor_last_slice INT UNSIGNED NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_users_email (email),
    INDEX idx_users_phone (phone)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS login_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    event_type VARCHAR(50) NOT NULL,
    ip_address VARCHAR(45) NULL,
    user_agent TEXT NULL,
    created_at DATETIME NOT NULL,
    INDEX idx_user_event_created (user_id, event_type, created_at),
    INDEX idx_lh_ip_created (ip_address, created_at),
    INDEX idx_login_history_created_at (created_at),
    INDEX idx_login_history_user_created (user_id, created_at),
    FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS customers (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    phone VARCHAR(50) NULL,
    email VARCHAR(190) NULL,
    address VARCHAR(255) NULL,
    is_walkin TINYINT(1) NOT NULL DEFAULT 0,
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_customers_deleted_id (deleted_at, id),
    INDEX idx_customers_walkin (is_walkin)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Suppliers directory (buying side; mirror of customers). UID prefix SUP-.
-- Backs supplier payables: a purchase may reference a supplier and track how
-- much we still owe them (see purchases.supplier_id / payment_status below).
CREATE TABLE IF NOT EXISTS suppliers (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    phone VARCHAR(50) NULL,
    email VARCHAR(190) NULL,
    address VARCHAR(255) NULL,
    note TEXT NULL,
    is_walkby TINYINT(1) NOT NULL DEFAULT 0,
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Recurring bills (rent, internet, electricity, subscriptions...). UID prefix
-- BILL-. A bill stores its amount + frequency; next_due_date advances each time
-- a period is paid (see bill_payments). Money OUT, single-currency for now.
CREATE TABLE IF NOT EXISTS bills (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    category VARCHAR(100) NULL DEFAULT 'Utilities',
    provider_name VARCHAR(190) NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    estimated_amount DECIMAL(32,16) NULL DEFAULT NULL,
    frequency VARCHAR(20) NOT NULL DEFAULT 'monthly',
    interval_days INT NULL,
    due_day INT NULL,
    first_due_date DATE NULL,
    next_due_date DATE NULL,
    cycle_anchor_date DATE NULL,
    is_archived TINYINT(1) NOT NULL DEFAULT 0,
    is_paused TINYINT(1) NOT NULL DEFAULT 0,
    active TINYINT(1) NOT NULL DEFAULT 1,
    default_cash_source VARCHAR(20) NOT NULL DEFAULT 'vault',
    receipt_ref VARCHAR(100) NULL,
    receipt_image LONGTEXT NULL,
    receipt_image_name VARCHAR(255) NULL,
    paused_at DATETIME NULL,
    paused_by INT NULL,
    resumed_at DATETIME NULL,
    resumed_by INT NULL,
    note TEXT NULL,
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_bills_active (active),
    INDEX idx_bills_archived (is_archived),
    INDEX idx_bills_paused (is_paused),
    INDEX idx_bills_category (category),
    INDEX idx_bills_next_due (next_due_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    color VARCHAR(50) NULL,
    description TEXT NULL,
    picture LONGTEXT NULL,
    picture_name VARCHAR(255) NULL,
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_categories_deleted_id (deleted_at, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    color VARCHAR(50) NULL,
    category_id INT NOT NULL,
    description TEXT NULL,
    picture LONGTEXT NULL,
    picture_name VARCHAR(255) NULL,
    price DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_reserved DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_writeoff DECIMAL(32,16) NOT NULL DEFAULT 0,
    stock_in_threshold DECIMAL(32,16) NULL,
    stock_low_threshold DECIMAL(32,16) NULL,
    display_decimals INT NULL,
    has_barcode TINYINT(1) NOT NULL DEFAULT 0,
    barcode VARCHAR(100) NULL DEFAULT NULL,
    barcode_type VARCHAR(30) NOT NULL DEFAULT 'CODE128',
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_products_stock (deleted_at, quantity),
    INDEX idx_products_cat_deleted (category_id, deleted_at),
    INDEX idx_products_deleted_id (deleted_at, id),
    INDEX idx_products_barcode (barcode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Multi-Barcode & QR Code Registry (1-to-N) (Mission 52)
CREATE TABLE IF NOT EXISTS product_barcodes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    product_id INT NOT NULL,
    barcode_value VARCHAR(100) NOT NULL UNIQUE,
    barcode_type VARCHAR(30) NOT NULL DEFAULT 'CODE128',
    prefix VARCHAR(20) NULL DEFAULT NULL,
    label VARCHAR(100) NULL DEFAULT NULL,
    is_primary TINYINT(1) NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_pb_product (product_id),
    INDEX idx_pb_value (barcode_value),
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS purchases (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    product_id INT NOT NULL,
    name VARCHAR(190) NOT NULL,
    price DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_remaining DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_reserved DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_sold DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_writeoff DECIMAL(32,16) NOT NULL DEFAULT 0,
    quantity_merged DECIMAL(32,16) NOT NULL DEFAULT 0,
    total DECIMAL(32,16) NOT NULL DEFAULT 0,
    date DATETIME NOT NULL,
    created_by INT NULL,
    -- Per-user cost/profit attribution: who this purchase's cost belongs to.
    -- NULL-able + back-filled to created_by; defaults to the creator on new rows.
    owner_user_id INT NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    supplier_id INT NULL,
    payment_status VARCHAR(20) NOT NULL DEFAULT 'paid',
    amount_paid DECIMAL(32,16) NOT NULL DEFAULT 0,
    paid_at DATETIME NULL,
    paid_by INT NULL,
    due_date DATETIME NULL,
    supplier_note TEXT NULL,
    -- Coin-as-product barter (settlement in a held product instead of cash).
    -- settle_kind: 'cash' (normal) | 'product' (this lot was BOUGHT by spending
    -- another coin you held) | 'received' (this lot CAME IN as payment for a sale).
    -- settle_product_id = the OTHER coin (spent for 'product', sold for 'received'),
    -- settle_quantity = its quantity, settle_order_id = the sale it came from.
    settle_kind VARCHAR(10) NOT NULL DEFAULT 'cash',
    settle_product_id INT NULL,
    settle_quantity DECIMAL(32,16) NULL,
    settle_order_id INT NULL,
    -- For a swap, the exact FIFO lots consumed of the spent coin, as JSON
    -- [{"lot_id":N,"quantity":"X"}] — lets a swap be UNWOUND exactly on delete
    -- (restore each lot's quantity_remaining/quantity_sold). NULL on cash rows
    -- and on legacy swaps (those fall back to a best-effort restore).
    settle_consumed TEXT NULL,
    -- Internal partner stock transfer & delegated purchase tracking.
    -- transfer_status: NULL (normal) | 'pending_transfer' | 'pending_delegated' | 'transferred' | 'cancelled'
    transfer_status VARCHAR(20) NULL DEFAULT NULL,
    transfer_to_user_id INT NULL DEFAULT NULL,
    transfer_valuation DECIMAL(32,16) NULL DEFAULT NULL,
    transfer_settlement_id INT NULL DEFAULT NULL,
    transfer_initiated_at DATETIME NULL DEFAULT NULL,
    transfer_initiated_by INT NULL DEFAULT NULL,
    paid_from VARCHAR(20) NOT NULL DEFAULT 'vault',
    status VARCHAR(30) NOT NULL DEFAULT 'active',
    is_merged_master TINYINT(1) NOT NULL DEFAULT 0,
    merged_into_id INT NULL DEFAULT NULL,
    merged_from_ids LONGTEXT NULL,
    merged_at DATETIME NULL DEFAULT NULL,
    merged_by INT NULL DEFAULT NULL,
    merge_cost_mode VARCHAR(30) NULL DEFAULT NULL,
    valuation_adjustment DECIMAL(32,16) NOT NULL DEFAULT 0,
    valuation_adjustment_reason TEXT NULL,
    initial_price DECIMAL(32,16) NULL,
    price_before DECIMAL(32,16) NULL,
    price_updated_at DATETIME NULL,
    price_updated_by INT NULL,
    created_from_order_id INT NULL DEFAULT NULL,
    created_from_purchase_id INT NULL DEFAULT NULL,
    INDEX idx_purchases_status (status),
    INDEX idx_purchases_merged_into (merged_into_id),
    INDEX idx_purchases_created_from_order (created_from_order_id),
    INDEX idx_purchases_created_from_purchase (created_from_purchase_id),
    INDEX idx_purchases_due (deleted_at, payment_status, due_date),
    INDEX idx_purchases_fifo (product_id, deleted_at, quantity_remaining),
    INDEX idx_purchases_supplier (supplier_id, deleted_at),
    INDEX idx_purchases_owner (owner_user_id, deleted_at),
    INDEX idx_purchases_active_stock (deleted_at, quantity_remaining, product_id),
    INDEX idx_purchases_deleted_id (deleted_at, id),
    INDEX idx_purchases_deleted_date_id (deleted_at, date, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS purchase_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    purchase_id INT NOT NULL,
    action VARCHAR(50) NOT NULL,
    price_before DECIMAL(32,16) NULL,
    price_after DECIMAL(32,16) NULL,
    valuation_delta DECIMAL(32,16) NULL,
    quantity_remaining DECIMAL(32,16) NULL,
    reason TEXT NULL,
    changes JSON NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_purchase_history_purchase (purchase_id),
    INDEX idx_purchase_history_edited_by (edited_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS orders (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    customer_id INT NOT NULL,
    items_summary TEXT NULL,
    total DECIMAL(32,16) NOT NULL DEFAULT 0,
    profit DECIMAL(32,16) NOT NULL DEFAULT 0,
    status VARCHAR(30) NOT NULL DEFAULT 'pending',
    created_by INT NULL,
    -- Per-user cost/profit attribution: who this order's revenue/COGS/profit
    -- belongs to. NULL-able + back-filled to created_by; defaults to the creator.
    owner_user_id INT NULL,
    date DATETIME NOT NULL,
    custom_sale TINYINT(1) NOT NULL DEFAULT 0,
    provider_name VARCHAR(190) NULL,
    service_name VARCHAR(190) NULL,
    service_description TEXT NULL,
    manual_cost DECIMAL(32,16) NOT NULL DEFAULT 0,
    products_cost DECIMAL(32,16) NOT NULL DEFAULT 0,
    completed_at DATETIME NULL,
    completed_by INT NULL,
    return_reason TEXT NULL,
    returned_at DATETIME NULL,
    returned_by INT NULL,
    return_strategy VARCHAR(30) NULL DEFAULT NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    custom_checklist LONGTEXT NULL,
    manual_costs_data LONGTEXT NULL,
    service_owners_data LONGTEXT NULL,
    created_from_order_id INT NULL,
    money_pending_at DATETIME NULL,
    money_pending_by INT NULL,
    paid_at DATETIME NULL,
    paid_by INT NULL,
    -- Customer receivables (mirror of supplier payables on purchases): how much
    -- the customer has paid so far toward an owed order, the rolling due date,
    -- and a free-text note for the built-in Walk-in (one-off) customer.
    amount_paid DECIMAL(32,16) NOT NULL DEFAULT 0,
    due_date DATETIME NULL,
    customer_note TEXT NULL,
    -- Coin-as-product barter: the customer paid in a held product instead of cash.
    -- settle_kind 'cash' (normal) | 'product' (paid in a coin); settle_product_id =
    -- the received coin, settle_quantity = how much, settle_purchase_id = the stock
    -- lot created for the received coin. The swap books NO profit (carry-over) — it
    -- surfaces when the received coin is later sold for cash.
    settle_kind VARCHAR(10) NOT NULL DEFAULT 'cash',
    settle_product_id INT NULL,
    settle_quantity DECIMAL(32,16) NULL,
    settle_purchase_id INT NULL,
    -- For a coin-sale, the exact FIFO lots consumed of the SOLD coin, as JSON
    -- [{"lot_id":N,"quantity":"X"}] — lets the sale be UNWOUND exactly on delete.
    -- NULL on cash orders and legacy swaps (best-effort restore is used there).
    settle_consumed TEXT NULL,
    parts_owner_profit DECIMAL(32,16) NOT NULL DEFAULT 0,
    service_owner_profit DECIMAL(32,16) NOT NULL DEFAULT 0,
    parts_cost_reimbursement DECIMAL(32,16) NOT NULL DEFAULT 0,
    agreement_status VARCHAR(30) NOT NULL DEFAULT 'all_accepted',
    has_refusal TINYINT(1) NOT NULL DEFAULT 0,
    is_locked_for_edit TINYINT(1) NOT NULL DEFAULT 0,
    agreement_version INT NOT NULL DEFAULT 1,
    refused_at DATETIME NULL,
    refused_by INT NULL,
    refusal_reason TEXT NULL,
    has_partial_returns TINYINT(1) NOT NULL DEFAULT 0,
    refusal_card_dismissed TINYINT(1) NOT NULL DEFAULT 0,
    -- Phone Sales & Repair Workshop Custody & Warranty (Mission 52)
    device_model VARCHAR(190) NULL,
    device_imei VARCHAR(100) NULL,
    device_passcode VARCHAR(100) NULL,
    device_condition TEXT NULL,
    device_custody_status VARCHAR(50) DEFAULT 'on_me' NULL,
    diagnostic_matrix LONGTEXT NULL,
    handover_qc_matrix LONGTEXT NULL,
    warranty_seal VARCHAR(100) NULL,
    warranty_period VARCHAR(100) NULL,
    warranty_expiry_date DATETIME NULL,
    INDEX idx_orders_date (date),
    INDEX idx_orders_status_deleted (status, deleted_at),
    INDEX idx_orders_owner (owner_user_id),
    INDEX idx_orders_created_from (created_from_order_id),
    INDEX idx_orders_deleted_date_id (deleted_at, date, id),
    INDEX idx_orders_imei (device_imei)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_items (
    id INT AUTO_INCREMENT PRIMARY KEY,
    order_id INT NOT NULL,
    product_id INT NULL,
    purchase_id INT NULL,
    name VARCHAR(190) NOT NULL,
