​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍
CREATE TABLE IF NOT EXISTS supplier_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    supplier_id INT NOT NULL,
    edited_by INT NULL,
    action VARCHAR(50) NOT NULL,
    changes JSON NULL,
    reason TEXT NULL,
    created_at DATETIME NOT NULL,
    FOREIGN KEY (supplier_id) REFERENCES suppliers(id),
    FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Per-period payment ledger for recurring bills (how much, when, by whom).
CREATE TABLE IF NOT EXISTS bill_payments (
    id INT AUTO_INCREMENT PRIMARY KEY,
    bill_id INT NOT NULL,
    period_id INT NULL,
    period_label VARCHAR(40) NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    paid_at DATETIME NOT NULL,
    paid_by INT NULL,
    note TEXT NULL,
    created_at DATETIME NOT NULL,
    voided_at DATETIME NULL,
    voided_by INT NULL,
    void_reason VARCHAR(255) NULL,
    FOREIGN KEY (bill_id) REFERENCES bills(id),
    FOREIGN KEY (paid_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- A bill "period" is one due cycle that needs paying. When a bill's due date
-- passes it auto-accrues an OPEN period (the obligation), so we always track how
-- much we owe the company even before anyone marks it paid. amount_paid rolls up
-- from bill_shares; status open|partial|settled. (per-user-cost-profit + bills.)
CREATE TABLE IF NOT EXISTS bill_periods (
    id INT AUTO_INCREMENT PRIMARY KEY,
    bill_id INT NOT NULL,
    period_label VARCHAR(40) NOT NULL,
    due_date DATE NULL,
    expected_amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    actual_amount DECIMAL(32,16) NULL,
    amount_paid DECIMAL(32,16) NOT NULL DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'open',
    opened_at DATETIME NOT NULL,
    opened_by INT NULL,
    settled_at DATETIME NULL,
    note TEXT NULL,
    created_at DATETIME NOT NULL,
    UNIQUE KEY uniq_bill_period (bill_id, period_label),
    FOREIGN KEY (bill_id) REFERENCES bills(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- One user's portion of a period. Participants are picked per period (equal or
-- manual). A share created for another user is 'pending' until they accept/edit;
-- self-made shares are 'accepted'. amount_paid rolls up from bill_share_payments.
CREATE TABLE IF NOT EXISTS bill_shares (
    id INT AUTO_INCREMENT PRIMARY KEY,
    period_id INT NOT NULL,
    bill_id INT NOT NULL,
    user_id INT NOT NULL,
    owed_amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    amount_paid DECIMAL(32,16) NOT NULL DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'accepted',
    requested_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    FOREIGN KEY (period_id) REFERENCES bill_periods(id),
    FOREIGN KEY (bill_id) REFERENCES bills(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Partial installments against a share. Each one is tagged source = cost|profit
-- (where the money comes from) and disposition = remove|keep (remove = actually
-- deduct it from the books / dashboard; keep = just record that it was paid, don't
-- deduct). Back-datable. This is the table the per-user dashboard reads to net
-- bills out of profit / into cost (only disposition='remove' rows affect the books).
CREATE TABLE IF NOT EXISTS bill_share_payments (
    id INT AUTO_INCREMENT PRIMARY KEY,
    share_id INT NOT NULL,
    bill_id INT NOT NULL,
    period_id INT NOT NULL,
    user_id INT NOT NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    source VARCHAR(10) NOT NULL DEFAULT 'profit',
    disposition VARCHAR(10) NOT NULL DEFAULT 'remove',
    paid_at DATETIME NOT NULL,
    paid_by INT NULL,
    note TEXT NULL,
    created_at DATETIME NOT NULL,
    voided_at DATETIME NULL,
    voided_by INT NULL,
    void_reason VARCHAR(255) NULL,
    FOREIGN KEY (share_id) REFERENCES bill_shares(id),
    FOREIGN KEY (bill_id) REFERENCES bills(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Audit trail for bill edits/deletes/restores (mirror of supplier_history).
CREATE TABLE IF NOT EXISTS bill_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    bill_id INT NOT NULL,
    edited_by INT NULL,
    action VARCHAR(50) NOT NULL,
    changes JSON NULL,
    reason TEXT NULL,
    created_at DATETIME NOT NULL,
    FOREIGN KEY (bill_id) REFERENCES bills(id),
    FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



CREATE TABLE IF NOT EXISTS customer_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    customer_id INT NOT NULL,
    edited_by INT NULL,
    action VARCHAR(50) NOT NULL,
    changes JSON NULL,
    reason TEXT NULL,
    created_at DATETIME NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customers(id),
    FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS service_templates (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(190) NOT NULL UNIQUE,
    checklist LONGTEXT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS system_logs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NULL,
    username VARCHAR(255) NULL,
    module VARCHAR(50) NOT NULL,
    action VARCHAR(50) NOT NULL,
    entity_id INT NULL,
    entity_name VARCHAR(255) NULL,
    details TEXT NULL,
    ip_address VARCHAR(45) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_module (module),
    INDEX idx_action (action),
    INDEX idx_user_id (user_id),
    INDEX idx_created_at (created_at),
    INDEX idx_user_action_created (user_id, action, created_at),
    INDEX idx_module_created (module, created_at),
    INDEX idx_module_entity (module, entity_id),
    INDEX idx_entity_id (entity_id),
    INDEX idx_action_created (action, created_at),
    INDEX idx_ip_created (ip_address, created_at),
    INDEX idx_syslogs_mod_act_ent (module, action, entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS backups (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE NOT NULL,
    filename VARCHAR(255) NOT NULL,
    filesize BIGINT NOT NULL DEFAULT 0,
    type ENUM('manual','automatic') NOT NULL DEFAULT 'manual',
    status ENUM('completed','failed') NOT NULL DEFAULT 'completed',
    error_message TEXT NULL,
    created_by INT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Unified Cash on Hand / Closet Vault (Master physical cash balance)
CREATE TABLE IF NOT EXISTS cash_vaults (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(100) NOT NULL DEFAULT 'Main Safe / Closet',
    starting_balance DECIMAL(32,16) NOT NULL DEFAULT 0,
    current_balance DECIMAL(32,16) NOT NULL DEFAULT 0,
    currency VARCHAR(10) NOT NULL DEFAULT 'DZD',
    is_primary TINYINT(1) NOT NULL DEFAULT 1,
    user_id INT NULL DEFAULT NULL,
    vault_type VARCHAR(50) NOT NULL DEFAULT 'main_safe',
    created_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Complete Ledger of Physical Cash Inflows & Outflows
CREATE TABLE IF NOT EXISTS cash_transactions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    vault_id INT NOT NULL,
    type VARCHAR(50) NOT NULL,
    direction VARCHAR(10) NOT NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    balance_before DECIMAL(32,16) NOT NULL DEFAULT 0,
    balance_after DECIMAL(32,16) NOT NULL DEFAULT 0,
    related_entity_type VARCHAR(50) NULL,
    related_entity_id INT NULL,
    note TEXT NULL,
    user_id INT NOT NULL,
    created_at DATETIME NOT NULL,
    INDEX idx_vault_id (vault_id),
    INDEX idx_user_id (user_id),
    INDEX idx_created_at (created_at),
    INDEX idx_ct_related (related_entity_type, related_entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One-Off Operating Expenses (Daily OPEX: supplies, cleaning, repairs, hospitality, transport)
CREATE TABLE IF NOT EXISTS operating_expenses (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    category VARCHAR(100) NOT NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    description TEXT NOT NULL,
    paid_from VARCHAR(20) NOT NULL DEFAULT 'vault',
    paid_from_type VARCHAR(20) NOT NULL DEFAULT 'vault',
    paid_by_user_id INT NOT NULL,
    beneficiary VARCHAR(190) NULL,
    receipt_ref VARCHAR(100) NULL,
    receipt_image LONGTEXT NULL,
    receipt_image_name VARCHAR(255) NULL,
    split_data JSON NULL,
    is_archived TINYINT(1) NOT NULL DEFAULT 0,
    note TEXT NULL,
    version INT NOT NULL DEFAULT 1,
    agreement_status VARCHAR(20) NOT NULL DEFAULT 'pending_acceptance',
    is_locked_for_edit TINYINT(1) NOT NULL DEFAULT 0,
    has_refusal TINYINT(1) NOT NULL DEFAULT 0,
    settlement_status VARCHAR(20) NOT NULL DEFAULT 'none',
    refused_at DATETIME NULL,
    refused_by INT NULL,
    refusal_reason TEXT NULL,
    last_edited_by INT NULL,
    last_edited_by_name VARCHAR(100) NULL,
    paid_at DATETIME NOT NULL,
    created_by INT NULL,
    edited_by INT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_oe_paid_by (paid_by_user_id),
    INDEX idx_oe_paid_at (paid_at),
    INDEX idx_oe_category (category),
    INDEX idx_oe_archived (is_archived),
    INDEX idx_oe_paid_from (paid_from),
    INDEX idx_oe_agreement (agreement_status),
    INDEX idx_oe_locked (is_locked_for_edit),
    INDEX idx_oe_refusal (has_refusal),
    INDEX idx_oe_deleted (deleted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Revisions History for Operating Expenses
CREATE TABLE IF NOT EXISTS operating_expense_revisions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    expense_id INT NOT NULL,
    version INT NOT NULL,
    snapshot JSON NOT NULL,
    settlement_ids JSON NULL,
    created_by INT NULL,
    created_at DATETIME NOT NULL,
    INDEX idx_oer_expense (expense_id),
    INDEX idx_oer_version (expense_id, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bill Groups (Grouping overhead recurring bills and categories)
CREATE TABLE IF NOT EXISTS bill_groups (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    description TEXT NULL,
    color VARCHAR(50) NULL DEFAULT NULL,
    icon VARCHAR(50) NULL DEFAULT NULL,
    category VARCHAR(50) NULL DEFAULT NULL,
    is_from_circle TINYINT(1) NOT NULL DEFAULT 0,
    source_circle_id INT NULL DEFAULT NULL,
    created_by INT NULL DEFAULT NULL,
    deleted_at DATETIME NULL DEFAULT NULL,
    deleted_by INT NULL DEFAULT NULL,
    delete_reason TEXT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NULL DEFAULT NULL,
    INDEX idx_bg_deleted (deleted_at),
    INDEX idx_bg_source_circle (source_circle_id),
    INDEX idx_bg_created_by (created_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Recurring Bills (Overhead templates: rent, electricity, internet, subscriptions)
CREATE TABLE IF NOT EXISTS recurring_bills (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    name VARCHAR(190) NOT NULL,
    category VARCHAR(100) NOT NULL DEFAULT 'Utilities',
    provider_name VARCHAR(190) NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    estimated_amount DECIMAL(32,16) NULL DEFAULT NULL,
    frequency VARCHAR(20) NOT NULL DEFAULT 'monthly',
    interval_days INT NULL,
    due_day INT NULL,
    first_due_date DATE NOT NULL,
    next_due_date DATE NULL,
    cycle_anchor_date DATE NULL,
    is_archived TINYINT(1) NOT NULL DEFAULT 0,
    group_id INT NULL DEFAULT NULL,
    is_from_circle TINYINT(1) NOT NULL DEFAULT 0,
    source_cycle_id INT NULL DEFAULT NULL,
    has_refusal TINYINT(1) NOT NULL DEFAULT 0,
    settlement_status VARCHAR(20) NOT NULL DEFAULT 'none',
    agreement_status VARCHAR(20) NOT NULL DEFAULT 'pending_acceptance',
    is_locked_for_edit TINYINT(1) NOT NULL DEFAULT 0,
    is_paused TINYINT(1) NOT NULL DEFAULT 0,
    active TINYINT(1) NOT NULL DEFAULT 1,
    default_cash_source VARCHAR(20) NOT NULL DEFAULT 'vault',
    receipt_ref VARCHAR(100) NULL,
    receipt_image LONGTEXT NULL,
    receipt_image_name VARCHAR(255) NULL,
    paused_at DATETIME NULL,
    paused_by INT NULL,
    resumed_at DATETIME NULL,
    resumed_by INT NULL,
    refused_at DATETIME NULL,
    refused_by INT NULL,
    refusal_reason TEXT NULL,
    note TEXT NULL,
    created_by INT NULL,
    edited_by INT NULL,
    last_edited_by INT NULL,
    last_edited_by_name VARCHAR(100) NULL,
    version INT NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    delete_reason TEXT NULL,
    INDEX idx_rb_active (active),
    INDEX idx_rb_archived (is_archived),
    INDEX idx_rb_group_id (group_id),
    INDEX idx_rb_has_refusal (has_refusal),
    INDEX idx_rb_settlement_status (settlement_status),
    INDEX idx_rb_agreement (agreement_status),
    INDEX idx_rb_paused (is_paused),
    INDEX idx_rb_category (category),
    INDEX idx_rb_next_due (next_due_date),
    INDEX idx_rb_deleted_archived (deleted_at, is_archived)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Recurring Bill Cycles (Transparent month-by-month payment ledger)
CREATE TABLE IF NOT EXISTS recurring_bill_cycles (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    bill_id INT NOT NULL,
    cycle_label VARCHAR(50) NOT NULL,
    due_date DATE NOT NULL,
    amount_expected DECIMAL(32,16) NOT NULL DEFAULT 0,
    amount_paid DECIMAL(32,16) NOT NULL DEFAULT 0,
    bill_created TINYINT(1) NOT NULL DEFAULT 0,
    bill_created_at DATETIME NULL,
    bill_created_by INT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'due',
    has_refusal TINYINT(1) NOT NULL DEFAULT 0,
    split_status VARCHAR(20) NOT NULL DEFAULT 'none',
    agreement_status VARCHAR(20) NOT NULL DEFAULT 'pending_acceptance',
    is_locked_for_edit TINYINT(1) NOT NULL DEFAULT 0,
    paid_from VARCHAR(20) NULL,
    paid_from_type VARCHAR(20) NULL,
    paid_at DATETIME NULL,
    declared_paid_at DATE NULL,
    invoice_date DATE NULL,
    received_date DATE NULL,
    paid_by INT NULL,
    receipt_ref VARCHAR(100) NULL,
    receipt_image LONGTEXT NULL,
    receipt_image_name VARCHAR(255) NULL,
    split_data JSON NULL,
    voided_at DATETIME NULL,
    voided_by INT NULL,
    void_reason VARCHAR(255) NULL,
    last_edited_by INT NULL,
    last_edited_by_name VARCHAR(100) NULL,
    note TEXT NULL,
    version INT NOT NULL DEFAULT 1,
    reset_count INT NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NULL,
    UNIQUE KEY uniq_bill_cycle (bill_id, cycle_label),
    INDEX idx_rbc_bill_id (bill_id),
    INDEX idx_rbc_due_date (due_date),
    INDEX idx_rbc_status (status),
    INDEX idx_rbc_has_refusal (has_refusal),
    INDEX idx_rbc_agreement (agreement_status),
    INDEX idx_rbc_voided (voided_at),
    INDEX idx_rbc_reset_count (reset_count),
    INDEX idx_rbc_uid (uid),
    INDEX idx_rbc_bill_due (bill_id, due_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Structured Audit Trail of Period Bill Reset Operations
CREATE TABLE IF NOT EXISTS recurring_bill_cycle_resets (
    id INT AUTO_INCREMENT PRIMARY KEY,
    cycle_id INT NOT NULL,
    bill_id INT NOT NULL,
    reset_number INT NOT NULL DEFAULT 1,
    reason TEXT NOT NULL,
    snapshot_before JSON NULL,
    refunds_summary JSON NULL,
    reset_by INT NOT NULL,
    reset_by_username VARCHAR(100) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_rbcr_cycle (cycle_id),
    INDEX idx_rbcr_bill (bill_id),
    INDEX idx_rbcr_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Granular Installment & Multi-Payer Split Allocations for Cycles
CREATE TABLE IF NOT EXISTS recurring_bill_cycle_payments (
    id INT AUTO_INCREMENT PRIMARY KEY,
    cycle_id INT NOT NULL,
    bill_id INT NOT NULL,
    user_id INT NOT NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    paid_from VARCHAR(20) NOT NULL DEFAULT 'vault',
    paid_at DATETIME NULL,
    receipt_ref VARCHAR(100) NULL,
    receipt_image LONGTEXT NULL,
    receipt_image_name VARCHAR(255) NULL,
    settlement_id INT NULL,
    note TEXT NULL,
    created_by INT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    voided_at DATETIME NULL,
    voided_by INT NULL,
    void_reason VARCHAR(255) NULL,
    INDEX idx_rbcp_cycle (cycle_id),
    INDEX idx_rbcp_bill (bill_id),
    INDEX idx_rbcp_user (user_id),
    INDEX idx_rbcp_settlement (settlement_id),
    INDEX idx_rbcp_voided (voided_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Complete Audit Trail for Expenses & Bills
CREATE TABLE IF NOT EXISTS expense_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    expense_id INT NULL,
    bill_id INT NULL,
    cycle_id INT NULL,
    edited_by INT NOT NULL,
    action VARCHAR(50) NOT NULL,
    changes JSON NULL,
    old_values JSON NULL,
    new_values JSON NULL,
    reason TEXT NULL,
    note TEXT NULL,
    created_at DATETIME NOT NULL,
    INDEX idx_eh_bill (bill_id),
    INDEX idx_eh_cycle (cycle_id),
    INDEX idx_edited_by (edited_by),
    INDEX idx_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Archived Bill Revisions & Cancel Edit Snapshots (Mission 106)
CREATE TABLE IF NOT EXISTS recurring_bill_revisions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    bill_id INT NOT NULL,
    version INT NOT NULL,
    bill_snapshot JSON NOT NULL,
    cycle_snapshot JSON NULL,
    settlement_ids JSON NULL,
    created_by INT NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cancelled_at DATETIME NULL,
    cancelled_by INT NULL,
    INDEX idx_rbr_bill (bill_id),
    INDEX idx_rbr_version (bill_id, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================================
-- Messaging & Notifications Subsystem (Mission 54)
-- =========================================================================

CREATE TABLE IF NOT EXISTS conversations (
    id INT AUTO_INCREMENT PRIMARY KEY,
    type ENUM('direct', 'group', 'channel') NOT NULL DEFAULT 'direct',
    title VARCHAR(150) NULL,
    description TEXT NULL,
    avatar_url LONGTEXT NULL,
    channel_post_permission ENUM('admins_only', 'everyone', 'selected') NOT NULL DEFAULT 'admins_only',
    created_by INT NOT NULL,
    last_message_id INT NULL,
    last_message_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX (last_message_at),
    INDEX (type),
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS conversation_members (
    id INT AUTO_INCREMENT PRIMARY KEY,
    conversation_id INT NOT NULL,
    user_id INT NOT NULL,
    is_admin TINYINT(1) NOT NULL DEFAULT 0,
    can_post TINYINT(1) NOT NULL DEFAULT 0,
    can_manage_members TINYINT(1) NOT NULL DEFAULT 0,
    is_pinned TINYINT(1) NOT NULL DEFAULT 0,
    is_muted TINYINT(1) NOT NULL DEFAULT 0,
    is_deleted_by_user TINYINT(1) NOT NULL DEFAULT 0,
    cleared_message_id INT NOT NULL DEFAULT 0,
    cleared_at DATETIME NULL,
    last_read_message_id INT NULL,
    last_read_at DATETIME NULL,
    joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_conv_user (conversation_id, user_id),
    INDEX (user_id),
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS messages (
    id INT AUTO_INCREMENT PRIMARY KEY,
    conversation_id INT NOT NULL,
    sender_id INT NULL,
    message_type ENUM('text', 'image', 'file', 'voice', 'system', 'video') NOT NULL DEFAULT 'text',
    body TEXT NULL,
    reply_to_message_id INT NULL,
    is_deleted TINYINT(1) NOT NULL DEFAULT 0,
    deleted_at DATETIME NULL,
    is_edited TINYINT(1) NOT NULL DEFAULT 0,
    edited_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX (conversation_id, created_at),
    INDEX (conversation_id, updated_at),
    INDEX (sender_id),
    INDEX idx_messages_conv_id (conversation_id, id),
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS message_attachments (
    id INT AUTO_INCREMENT PRIMARY KEY,
    message_id INT NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    file_path VARCHAR(255) NOT NULL,
    file_type VARCHAR(100) NOT NULL,
    file_size INT NOT NULL DEFAULT 0,
    duration_seconds INT NULL,
    poster_path VARCHAR(255) NULL,
    poster_data LONGTEXT NULL,
    width INT NULL,
    height INT NULL,
    file_data LONGTEXT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX (message_id),
    INDEX idx_attachments_file_path (file_path),
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS message_user_deletions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    message_id INT NOT NULL,
    user_id INT NOT NULL,
    deleted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_msg_user (message_id, user_id),
    INDEX (user_id),
    INDEX idx_mud_user_msg (user_id, message_id),
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS message_stars (
    id INT AUTO_INCREMENT PRIMARY KEY,
    message_id INT NOT NULL,
    user_id INT NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_msg_star_user (message_id, user_id),
    INDEX (user_id),
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS message_read_receipts (
    id INT AUTO_INCREMENT PRIMARY KEY,
    message_id INT NOT NULL,
    user_id INT NOT NULL,
    read_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_msg_read_user (message_id, user_id),
    INDEX idx_mrr_user (user_id),
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notifications (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    type ENUM('message', 'channel_message', 'due_payable', 'due_receivable', 'order_due', 'stock_alert', 'system', 'schedule', 'bill', 'expense', 'settlement') NOT NULL DEFAULT 'system',
    title VARCHAR(255) NOT NULL,
    body TEXT NULL,
    action_url VARCHAR(255) NULL,
    entity_type VARCHAR(50) NULL,
    entity_id INT NULL,
    is_read TINYINT(1) NOT NULL DEFAULT 0,
    stage_tag VARCHAR(50) NULL DEFAULT NULL,
    deleted_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX (user_id, is_read, created_at),
    INDEX (user_id, deleted_at, is_read),
    INDEX (user_id, entity_type, entity_id, stage_tag),
    INDEX idx_notifications_user_del_created (user_id, deleted_at, created_at),
    INDEX (type),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notification_suppressions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    entity_type VARCHAR(50) NOT NULL,
    entity_id INT NULL,
    stage_tag VARCHAR(50) NULL,
    suppressed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_notif_suppression (user_id, entity_type, entity_id, stage_tag),
    INDEX idx_notif_suppression_user (user_id, entity_type),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS schedules (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT NULL,
    target_datetime DATETIME NOT NULL,
    priority ENUM('normal', 'high', 'urgent') NOT NULL DEFAULT 'normal',
    visibility ENUM('only_me', 'selected_users', 'everyone') NOT NULL DEFAULT 'only_me',
    status ENUM('pending', 'due', 'completed', 'cancelled') NOT NULL DEFAULT 'pending',
    created_by INT NOT NULL,
    is_notified TINYINT(1) NOT NULL DEFAULT 0,
    completed_at DATETIME NULL,
    completed_by INT NULL,
    cancelled_at DATETIME NULL,
    cancelled_by INT NULL,
    deleted_at DATETIME NULL,
    deleted_by INT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_target_status_notified (target_datetime, status, is_notified),
    INDEX idx_creator_visibility (created_by, visibility, status),
    INDEX idx_deleted_at (deleted_at),
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (completed_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (cancelled_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (deleted_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS schedule_assignees (
    id INT AUTO_INCREMENT PRIMARY KEY,
    schedule_id INT NOT NULL,
    user_id INT NOT NULL,
    is_read TINYINT(1) NOT NULL DEFAULT 0,
    notified_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_schedule_user (schedule_id, user_id),
    INDEX idx_user_read (user_id, is_read),
    FOREIGN KEY (schedule_id) REFERENCES schedules(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ALTER TABLE products ADD CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id);
ALTER TABLE purchases ADD CONSTRAINT fk_purchases_product FOREIGN KEY (product_id) REFERENCES products(id);
-- purchases.supplier_id is intentionally NOT a FK: it's a newer optional column
-- (like created_by / paid_by) added during v1 dev, and an FK referencing a
-- column that SchemaSync adds *after* applySchema would break "Verify & build"
-- on existing databases. Supplier existence is validated in PurchasesController.
ALTER TABLE orders ADD CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers(id);
ALTER TABLE order_items ADD CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders(id);

-- Schema version tracking (single row, id = 1). The running code stamps this
-- to its own version on install; see src/Version.php + migrations/registry.php.
CREATE TABLE IF NOT EXISTS system_version (
    id INT PRIMARY KEY,
    version INT NOT NULL,
    app_version VARCHAR(20) NULL,
    updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- Partner Equity & Settlement System
-- ============================================================
CREATE TABLE IF NOT EXISTS partner_settlements (
    id INT AUTO_INCREMENT PRIMARY KEY,
    uid VARCHAR(50) UNIQUE DEFAULT NULL,
    payer_user_id INT NOT NULL,
    payee_user_id INT NOT NULL,
    amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    original_amount DECIMAL(32,16) NULL,
    settlement_type VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'pending',
    acceptance_status VARCHAR(20) NOT NULL DEFAULT 'pending',
    accepted_at DATETIME NULL,
    accepted_by INT NULL,
    release_status VARCHAR(20) NOT NULL DEFAULT 'locked',
    released_amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    settled_amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    paid_amount DECIMAL(32,16) NOT NULL DEFAULT 0,
    waterfall_priority INT NOT NULL DEFAULT 1,
    waterfall_role VARCHAR(20) NOT NULL DEFAULT 'cost',
    linked_settlement_id INT NULL DEFAULT NULL,
    target_source VARCHAR(20) NOT NULL DEFAULT 'vault',
    settled_source VARCHAR(20) NULL DEFAULT NULL,
    related_entity_type VARCHAR(50) NULL,
    related_entity_id INT NULL,
    order_item_id INT NULL,
    related_entity_uid VARCHAR(50) NULL,
    bill_id INT NULL,
    cycle_id INT NULL,
    description TEXT NULL,
    details JSON NULL,
    released_at DATETIME NULL,
    released_by INT NULL,
    settled_at DATETIME NULL,
    settled_by INT NULL,
    settled_via_transaction_id INT NULL,
    disputed_at DATETIME NULL,
    disputed_by INT NULL,
    dispute_reason TEXT NULL,
    refused_at DATETIME NULL,
    refused_by INT NULL,
    refusal_reason TEXT NULL,
    adjusted_at DATETIME NULL,
    adjusted_by INT NULL,
    adjustment_reason TEXT NULL,
    cancelled_at DATETIME NULL,
    cancelled_by INT NULL,
    cancel_reason TEXT NULL,
    payment_demand_status VARCHAR(20) NULL DEFAULT NULL,
    payment_demand_at DATETIME NULL,
    payment_demand_paid_at DATETIME NULL,
    removal_request_status VARCHAR(20) NULL DEFAULT NULL,
    removal_requested_at DATETIME NULL,
    removal_refund_eligible TINYINT(1) NOT NULL DEFAULT 0,
    created_by INT NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (payer_user_id) REFERENCES users(id),
    FOREIGN KEY (payee_user_id) REFERENCES users(id),
    INDEX idx_ps_payer (payer_user_id, status),
    INDEX idx_ps_payee (payee_user_id, status),
    INDEX idx_ps_status (status),
    INDEX idx_ps_acceptance (acceptance_status),
    INDEX idx_ps_type (settlement_type),
    INDEX idx_ps_release (release_status, status),
    INDEX idx_ps_related (related_entity_type, related_entity_id),
    INDEX idx_ps_order_item (order_item_id),
    INDEX idx_ps_bill_id (bill_id, status),
    INDEX idx_ps_cycle_id (cycle_id, status),
    INDEX idx_ps_cycle_acceptance (cycle_id, acceptance_status),
    INDEX idx_ps_waterfall (linked_settlement_id, waterfall_priority)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Real-time Entity Version Vector for Zero-Latency Multi-Client Synchronization
CREATE TABLE IF NOT EXISTS system_entity_versions (
    entity_name VARCHAR(50) PRIMARY KEY,
    version BIGINT UNSIGNED NOT NULL DEFAULT 1,
